#include <vector>
#include <queue>
#include <algorithm>

class Solution {
public:
    int maxEvents(std::vector<std::vector<int>>& events) {
        std::sort(events.begin(), events.end());
        int totalDays = 0;
        for (const auto& e : events) totalDays = std::max(totalDays, e[1]);
        std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;
        int eventIdx = 0, n = events.size(), attended = 0;
        for (int day = 1; day <= totalDays; ++day) {
            while (eventIdx < n && events[eventIdx][0] == day) {
                minHeap.push(events[eventIdx++][1]);
            }
            while (!minHeap.empty() && minHeap.top() < day) {
                minHeap.pop();
            }
            if (!minHeap.empty()) {
                minHeap.pop();
                attended++;
            }
            if (eventIdx >= n && minHeap.empty()) break;
        }
        return attended;
    }
};

import java.util.*;

class Solution {
    public int maxEvents(int[][] events) {
        Arrays.sort(events, (a, b) -> Integer.compare(a[0], b[0]));
        int totalDays = 0;
        for (int[] e : events) totalDays = Math.max(totalDays, e[1]);
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        int eventIdx = 0, n = events.length, attended = 0;
        for (int day = 1; day <= totalDays; day++) {
            while (eventIdx < n && events[eventIdx][0] == day) {
                minHeap.offer(events[eventIdx++][1]);
            }
            while (!minHeap.isEmpty() && minHeap.peek() < day) {
                minHeap.poll();
            }
            if (!minHeap.isEmpty()) {
                minHeap.poll();
                attended++;
            }
            if (eventIdx >= n && minHeap.isEmpty()) break;
        }
        return attended;
    }
}

var maxEvents = function(events) {
    events.sort((a, b) => a[0] - b[0]);
    let totalDays = 0;
    for (const e of events) if (e[1] > totalDays) totalDays = e[1];
    const minHeap = [];
    const push = (val) => {
        minHeap.push(val);
        let i = minHeap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (minHeap[p] <= minHeap[i]) break;
            [minHeap[p], minHeap[i]] = [minHeap[i], minHeap[p]];
            i = p;
        }
    };
    const pop = () => {
        const top = minHeap[0];
        const bottom = minHeap.pop();
        if (minHeap.length > 0) {
            minHeap[0] = bottom;
            let i = 0;
            while (true) {
                let left = 2 * i + 1, right = 2 * i + 2, best = i;
                if (left < minHeap.length && minHeap[left] < minHeap[best]) best = left;
                if (right < minHeap.length && minHeap[right] < minHeap[best]) best = right;
                if (best === i) break;
                [minHeap[i], minHeap[best]] = [minHeap[best], minHeap[i]];
                i = best;
            }
        }
        return top;
    };
    let eventIdx = 0, n = events.length, attended = 0;
    for (let day = 1; day <= totalDays; day++) {
        while (eventIdx < n && events[eventIdx][0] === day) {
            push(events[eventIdx++][1]);
        }
        while (minHeap.length > 0 && minHeap[0] < day) {
            pop();
        }
        if (minHeap.length > 0) {
            pop();
            attended++;
        }
        if (eventIdx >= n && minHeap.length === 0) break;
    }
    return attended;
};
